.env-select {
  position: relative;
  margin: 8px 0 12px;
}

.env-select-trigger {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  min-height: 34px;
  text-align: left;
  white-space: normal;
}

.env-select-value {
  display: flex;
  flex: 1 1 auto;
  flex-wrap: wrap;
  gap: 4px;
  align-items: center;
  min-width: 0;
}

.env-select-placeholder {
  color: #777;
}

.env-select-chip {
  display: inline-block;
  max-width: 220px;
  overflow: hidden;
  padding: 1px 8px;
  text-overflow: ellipsis;
  white-space: nowrap;
  background-color: #f0f0f0;
  border: 1px solid #dedede;
  border-radius: 10px;
}

.env-select-menu {
  right: 0;
  min-width: 0;
  padding: 0;
  overflow: hidden;
}

.env-select-search {
  padding: 8px;
  border-bottom: 1px solid #dedede;
}

.env-select-list {
  max-height: 208px;
  overflow-y: auto;
}

.env-select-option {
  display: flex;
  gap: 8px;
  align-items: center;
  margin: 0;
  padding: 5px 12px;
  font-weight: normal;
  cursor: pointer;
}

.env-select-option:hover {
  background-color: #f5f5f5;
}

.env-select-option input {
  flex: 0 0 auto;
  margin: 0;
  cursor: inherit;
}

.env-select-option-label {
  flex: 1 1 auto;
  min-width: 0;
  overflow-wrap: anywhere;
}

.env-select-all {
  font-weight: bold;
  border-bottom: 1px solid #dedede;
}

.env-select-protected {
  color: #999;
  cursor: not-allowed;
}

.env-select-protected:hover {
  background-color: transparent;
}

.env-select-badge {
  flex: 0 0 auto;
  padding: 0 6px;
  font-size: 10px;
  font-weight: normal;
  text-transform: uppercase;
  color: #6b6b6b;
  background-color: #f0f0f0;
  border-radius: 10px;
}

.env-select-empty {
  padding: 16px 12px;
  color: #777;
  text-align: center;
}

.env-select-footer {
  display: flex;
  gap: 12px;
  align-items: center;
  justify-content: space-between;
  padding: 6px 12px;
  font-size: 12px;
  color: #6b6b6b;
  background-color: #f5f5f5;
  border-top: 1px solid #dedede;
}

.env-select-clear {
  padding: 0;
  font-size: 12px;
  color: #337ab7;
  background: none;
  cursor: pointer;
}

.env-select-clear:disabled {
  color: #999;
  cursor: not-allowed;
}
